  ---@param err any #the pcall error slot; traceback wants a string, so hand it the raise's own text 
-- Why `any`: the pcall error slot, which is an object rather than a string on some raises; the library tostring's it before logging
  ---@param event string #the net event name, recorded as errorInfo.event
  ---@return nil #nothing comes back; the console line and a diagnostics counter are the whole effect
---@overload
  ---@param err any #the pcall error slot 
-- Why `any`: the pcall error slot, which is an object rather than a string on some raises; the library tostring's it before logging
  ---@param context? string #a label for where it happened; nil falls back to "Unknown"
  ---@return nil #nothing comes back; the console line and a diagnostics counter are the whole effect
---@overload
function AutoLogError.server(err, event) end
function AutoLogError.client(err, context) end

---@overload fun(...)
  ---@param name string #a previously registered name, quoted in the raise message on refusal
  ---@param ... ... #the unbounded tail, forwarded bare -- no pack, no local list, nothing dropped
  ---@return any #the handler's results, unpacked with their count so a nil in the middle survives. A refusal RAISES rather than returning, so a caller that does not pcall takes the hit 
-- Why `any`: the handler's own result list, whose arity and types the handler alone decides
---@overload
  ---@param name string #a previously registered name, stringified into the raise message
  ---@param ... ... #the unbounded tail, forwarded bare
  ---@return any, any #ONLY the handler's FIRST TWO results -- a third is dropped with no error, and that is a real defect rather than a documented cap. A refusal RAISES 
-- Why `any`: the handler's own result list, whose arity and types the handler alone decides
---@overload
function AwaitCallback.server(name, ...) end
function AwaitCallback.client(name, ...) end

--- Cis.callback.awaitClient(src, name, ...)
---@param name string #the callback the CLIENT answers
---@param target integer #a connected player id; a plausible-but-absent id is refused rather than parked
---@param ... ... #the unbounded tail; the client caps it at 32 args
---@return boolean, any #true plus the client's results; false plus a reason for a bad target, a disconnect, a timeout or a drop. A promise rejection raises inside the await, and a pcall is what turns it into a value 
-- Why `any`: the handler's own result list, whose arity and types the handler alone decides
--- realm: server
function AwaitCallbackClient(name, target, ...) end

--- no proxy equivalent; exports["cis_libs"]:BreakDoor(identifier)
