--- realm: server
function BreakDoor(identifier) end

---@overload fun(...)
  ---@param name string #a previously registered name
  ---@param cb? function #invoked with the whole reply; a non-function refuses and calls nothing at all
  ---@param ... ... #the unbounded tail, packed then forwarded whole -- nothing past N is dropped
  ---@return nil #nothing comes back on any path; the outcome only ever arrives as cb(false, 'unknown') or cb(false, 'error')
---@overload
  ---@param name string #the handler name, shipped as the event's first field
  ---@param cb? function #invoked as cb(ok, ...) with the whole reply. A NIL cb is legal and silently discards the answer
  ---@param ... ... #the unbounded tail, forwarded bare; packing happens on arrival and values are serialised, so no function can cross
  ---@return nil #nothing comes back and the pending key is discarded. A refusal is never a return: it arrives later as cb(false, reason), one of 'timeout', 'rate', 'unknown' or 'error'
---@overload
function CallCallback.server(name, cb, ...) end
function CallCallback.client(name, cb, ...) end

--- Cis.callback.callClient(src, name, cb, ...)
---@param name string #the callback the CLIENT answers
---@param target integer #a connected player server id; anything else is refused and nobody is told
---@param cb? function #a consumer-side function, consumed on the consumer side, so it does not cross
---@param ... ... #the unbounded tail; the client caps it at 32 args and answers "too large"
---@return integer #the pending key. A bad target returns NOTHING and instead calls cb(false, reason)
--- realm: server
function CallCallbackClient(name, target, cb, ...) end

